      serverUrl: { es: "URL base del servidor Bitwarden. La salud se chequea en /alive." },
      email: { es: "Email de la cuenta, solo para mostrar." },
      clientId: { es: "Client id de la API key, usado para \"bw login --apikey\" desatendido." },
